"""Property-based tests for clinical_math (hypothesis + pytest)."""

import pytest
from hypothesis import given, settings
from hypothesis import strategies as st

from clinical_math import crcl, mean_arterial_pressure

# Valid physiological input ranges (synthetic/educational values)
SBP = st.integers(min_value=60, max_value=300)
DBP = st.integers(min_value=20, max_value=199)
VALID_BP_PAIRS = st.tuples(SBP, DBP).filter(lambda p: p[1] < p[0])

AGE = st.integers(min_value=18, max_value=110)
WEIGHT = st.integers(min_value=20, max_value=300)
SCR = st.integers(min_value=1, max_value=1500)  # scr in 0.01 mg/dL units


def _scr(units_of_hundredth):
    return units_of_hundredth / 100.0


# ---------------------------------------------------------------- MAP


@settings(max_examples=100)
@given(pair=VALID_BP_PAIRS)
def test_map_strictly_between_dbp_and_sbp(pair):
    sbp, dbp = pair
    map_value = mean_arterial_pressure(sbp, dbp)
    assert dbp < map_value < sbp


@settings(max_examples=100)
@given(
    pair=VALID_BP_PAIRS,
    delta=st.integers(min_value=1, max_value=300),
)
def test_map_monotone_in_sbp(pair, delta):
    sbp, dbp = pair
    if sbp + delta <= 300:
        assert (
            mean_arterial_pressure(sbp, dbp)
            < mean_arterial_pressure(sbp + delta, dbp)
        )


@settings(max_examples=100)
@given(
    pair=VALID_BP_PAIRS,
    delta=st.integers(min_value=1, max_value=180),
)
def test_map_monotone_in_dbp(pair, delta):
    sbp, dbp = pair
    if dbp + delta < sbp:
        assert (
            mean_arterial_pressure(sbp, dbp)
            < mean_arterial_pressure(sbp, dbp + delta)
        )


# ---------------------------------------------------------------- CrCl

CRCL_ARGS = st.tuples(AGE, WEIGHT, SCR)


@settings(max_examples=100)
@given(args=CRCL_ARGS, d_age=st.integers(min_value=1, max_value=92))
def test_crcl_decreases_with_age(args, d_age):
    age, weight, scr_units = args
    if age + d_age <= 110:
        younger = crcl(age, weight, _scr(scr_units), female=False)
        older = crcl(age + d_age, weight, _scr(scr_units), female=False)
        assert older < younger


@settings(max_examples=100)
@given(args=CRCL_ARGS, d_weight=st.integers(min_value=1, max_value=280))
def test_crcl_increases_with_weight(args, d_weight):
    age, weight, scr_units = args
    if weight + d_weight <= 300:
        lighter = crcl(age, weight, _scr(scr_units), female=False)
        heavier = crcl(age, weight + d_weight, _scr(scr_units), female=False)
        assert lighter < heavier


@settings(max_examples=100)
@given(args=CRCL_ARGS, d_scr=st.integers(min_value=1, max_value=1400))
def test_crcl_decreases_as_creatinine_rises(args, d_scr):
    age, weight, scr_units = args
    if scr_units + d_scr <= 1500:
        lower = crcl(age, weight, _scr(scr_units), female=False)
        higher = crcl(age, weight, _scr(scr_units + d_scr), female=False)
        assert higher < lower


@settings(max_examples=100)
@given(args=CRCL_ARGS)
def test_female_result_is_exactly_0_85_times_male(args):
    age, weight, scr_units = args
    scr = _scr(scr_units)
    male = crcl(age, weight, scr, female=False)
    female = crcl(age, weight, scr, female=True)
    assert female == pytest.approx(0.85 * male, rel=1e-12)


@settings(max_examples=100)
@given(args=CRCL_ARGS)
def test_crcl_positive_in_valid_range(args):
    age, weight, scr_units = args
    assert crcl(age, weight, _scr(scr_units), female=True) > 0

